STAGES = [('locate', 'stages/01_locate.py', '# locate: find the rod with own vision (mask + depth of the two global cameras, cylinder fit);\n# the tracker is only printed for comparison (r01: it goes stale / wrong when the hand occludes the rod).\nfrom assembly_policy.sim.robot import quat_to_mat, mat_to_quat, quat_mul, quat_conj, axis_angle_quat\nnp.set_printoptions(precision=4, suppress=True)\n\n_M = api.part_model()\nPB0 = np.asarray(_M["bbox_min"], float)\nPB1 = np.asarray(_M["bbox_max"], float)\n_ext = PB1 - PB0\nAX = int(np.argmax(_ext))                      # long axis of the rod in the part frame\n_mid = (PB0 + PB1) / 2\nE0 = _mid.copy(); E0[AX] = PB0[AX]             # the two axis end points in the part frame\nE1 = _mid.copy(); E1[AX] = PB1[AX]\nL = float(_ext[AX])\nRAD = float(np.delete(_ext, AX).max() / 2)\nEZ = np.array([0.0, 0.0, 1.0])\n\n\ndef Tm(p, R):\n    M = np.eye(4); M[:3, :3] = R; M[:3, 3] = p\n    return M\n\n\ndef Tinv(M):\n    R = M[:3, :3]; p = M[:3, 3]\n    return Tm(-R.T @ p, R.T)\n\n\ndef rotz(a):\n    c, s = np.cos(a), np.sin(a)\n    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1.0]])\n\n\ndef unit(v):\n    v = np.asarray(v, float)\n    return v / max(np.linalg.norm(v), 1e-12)\n\n\ndef tcp_T():\n    o = api.observe()\n    return Tm(np.asarray(o["tcp_pos"], float), quat_to_mat(np.asarray(o["tcp_quat"], float)))\n\n\ndef tracker():\n    p, q, c = api.locate_part()\n    if p is None:\n        return None\n    p = np.asarray(p, float); R = quat_to_mat(np.asarray(q, float))\n    return p + R @ E0, p + R @ E1, c\n\n\ndef backproject(c, sel):\n    vs, us = np.nonzero(sel)\n    d = c["depth"][vs, us]\n    K = np.asarray(c["K"], float)\n    P = np.stack([(us + .5 - K[0, 2]) / K[0, 0] * d, -(vs + .5 - K[1, 2]) / K[1, 1] * d, -d], 1)\n    return np.asarray(c["cam_pos"], float) + P @ np.asarray(c["cam_R"], float).T\n\n\ndef fit_rod(names=("global", "global2"), cams=None):\n    """Cylinder fit (known radius) to the part-mask depth points. Returns dict with axis dir a,\n    axis point, visible end points p0/p1 (along a), extent, rms, n."""\n    cams = cams if cams is not None else api.camera()\n    P, C = [], []\n    for n in names:\n        c = cams[n]\n        m = np.asarray(c["mask"], bool)\n        # drop mask boundary pixels (depth may belong to the background)\n        inner = m.copy()\n        inner[1:, :] &= m[:-1, :]; inner[:-1, :] &= m[1:, :]\n        inner[:, 1:] &= m[:, :-1]; inner[:, :-1] &= m[:, 1:]\n        if inner.sum() < 30:\n            continue\n        pts = backproject(c, inner)\n        P.append(pts); C.append(np.repeat(np.asarray(c["cam_pos"], float)[None], len(pts), 0))\n    if not P:\n        return None\n    P = np.concatenate(P); C = np.concatenate(C)\n    for _ in range(2):                                  # robust line\n        mu = np.median(P, 0)\n        a = np.linalg.svd(P - mu, full_matrices=False)[2][0]\n        dperp = np.linalg.norm((P - mu) - np.outer((P - mu) @ a, a), axis=1)\n        keep = dperp < 0.012\n        P, C = P[keep], C[keep]\n        if len(P) < 30:\n            return None\n    mu = P.mean(0)\n    a = np.linalg.svd(P - mu, full_matrices=False)[2][0]\n    b1 = unit(np.cross(a, EZ) if abs(a[2]) < 0.9 else np.cross(a, [1.0, 0, 0]))\n    b2 = np.cross(a, b1)\n    X = np.stack([(P - mu) @ b1, (P - mu) @ b2], 1)\n    vc = (C - P).mean(0)\n    vc2 = unit(np.array([vc @ b1, vc @ b2]))\n    cc = X.mean(0) - vc2 * RAD * 0.75\n    w = np.ones(len(X), bool)\n    for it in range(25):\n        d = X[w] - cc\n        r = np.linalg.norm(d, axis=1) + 1e-9\n        J = -d / r[:, None]\n        cc = cc + np.linalg.lstsq(J, -(r - RAD), rcond=None)[0]\n        if it == 12:\n            w = np.abs(np.linalg.norm(X - cc, axis=1) - RAD) < 0.0015\n    res = np.abs(np.linalg.norm(X[w] - cc, axis=1) - RAD)\n    ap = mu + cc[0] * b1 + cc[1] * b2\n    t = (P[w] - ap) @ a\n    t0, t1 = np.percentile(t, 0.3), np.percentile(t, 99.7)\n    return dict(a=a, ap=ap, p0=ap + t0 * a, p1=ap + t1 * a, ext=float(t1 - t0),\n                rms=float(np.sqrt((res ** 2).mean())), n=int(w.sum()))\n\n\ndef rod_ends(f, anchor_far_from=None):\n    """Both rod ends (length L) from a fit; if the visible extent is short, anchor on the visible end\n    farther from `anchor_far_from` (the other end is hidden by the fingers)."""\n    if f["ext"] > L - 0.004 or anchor_far_from is None:\n        c = (f["p0"] + f["p1"]) / 2\n        return c - f["a"] * L / 2, c + f["a"] * L / 2\n    d0 = np.linalg.norm(f["p0"] - anchor_far_from); d1 = np.linalg.norm(f["p1"] - anchor_far_from)\n    if d0 > d1:\n        return f["p0"], f["p0"] + f["a"] * L\n    return f["p1"] - f["a"] * L, f["p1"]\n\n\ndef heightmap_points(cams, center, radius=0.15):\n    pts = []\n    for n in ("global", "global2"):\n        c = cams[n]\n        sel = ~np.asarray(c["mask"], bool) & (c["depth"] > 0)\n        sel[::2, :] = False; sel[:, ::2] = False\n        P = backproject(c, sel)\n        P = P[np.linalg.norm(P[:, :2] - center[:2], axis=1) < radius]\n        pts.append(P)\n    return np.concatenate(pts)\n\n\nOBS0 = api.observe()\nGOAL_P = np.asarray(OBS0["goal_pos"], float)\nGOAL_R = quat_to_mat(np.asarray(OBS0["goal_quat"], float))\n_g0, _g1 = GOAL_P + GOAL_R @ E0, GOAL_P + GOAL_R @ E1\nGB, GT = (_g0, _g1) if _g0[2] <= _g1[2] else (_g1, _g0)   # goal bottom / top axis points\nprint("goal bottom", GB, "top", GT, "L", L, "RAD", RAD)\n\nCAMS0 = api.camera()\nFIT0 = fit_rod(cams=CAMS0)\ntr = tracker()\nok = False\nev = "no mask fit"\nif FIT0 is not None:\n    R0E0, R0E1 = rod_ends(FIT0)\n    ROD_CTR0 = (R0E0 + R0E1) / 2\n    BOARD_Z = ROD_CTR0[2] - RAD\n    HM = heightmap_points(CAMS0, ROD_CTR0)\n    dtr = np.linalg.norm(((tr[0] + tr[1]) / 2 - ROD_CTR0)[:2]) * 1000 if tr else -1\n    ok = (abs(FIT0["a"][2]) < 0.3 and FIT0["rms"] < 0.0012 and FIT0["n"] > 300\n          and abs(FIT0["ext"] - L) < 0.006 and 0.0 < ROD_CTR0[2] < 0.04)\n    ev = (f"fit ctr={np.round(ROD_CTR0, 4).tolist()} axis={np.round(FIT0[\'a\'], 2).tolist()} ext={FIT0[\'ext\']*1000:.1f}mm "\n          f"rms={FIT0[\'rms\']*1000:.2f}mm n={FIT0[\'n\']} tracker-vs-fit xy={dtr:.1f}mm")\nprint(ev)\nstage_done(ok, ev)\n', True), ('grasp', 'stages/02_grasp.py', '# grasp: top-down pinch of the lying rod near the end that will be on top, fingers pre-opened narrow,\n# grasp point chosen free of neighbouring obstacles (depth heightmap) and with a reachable insertion; lift.\nTIP_BELOW_TCP = 0.009    # r01: fingertips hit the board with the TCP 9 mm above it\nTCP_ABOVE_BOARD = 0.0115\nW_PRE = 0.03             # pre-grasp opening\nH_PRE = 0.035            # rod bottom above the goal bottom before the final descent\nH_HIGH = 0.12\n\n\ndef rot_a_to_b(a, b):\n    a, b = unit(a), unit(b)\n    v = np.cross(a, b); s = np.linalg.norm(v); c = float(a @ b)\n    if s < 1e-9:\n        if c > 0:\n            return np.eye(3)\n        p = unit(np.cross(a, [1.0, 0, 0]) if abs(a[0]) < 0.9 else np.cross(a, [0, 1.0, 0]))\n        return 2 * np.outer(p, p) - np.eye(3)\n    k = v / s\n    Kx = np.array([[0, -k[2], k[1]], [k[2], 0, -k[0]], [-k[1], k[0], 0]])\n    return np.eye(3) + s * Kx + (1 - c) * Kx @ Kx\n\n\ndef plan_insert(Eb, Ec, q_seed, verbose=False):\n    """Eb/Ec = rod bottom/top axis points in the TCP frame. Rod vertical, bottom at GB(+dz),\n    yaw about the vertical swept. Returns the cheapest reachable plan or None."""\n    Rb = rot_a_to_b(Eb - Ec, -EZ)\n    best = None\n    lim = np.asarray(api.constants()["joint_limits"], float)\n    for psi in np.linspace(-np.pi, np.pi, 24, endpoint=False):\n        R = rotz(psi) @ Rb\n        poses = {}\n        q_prev = q_seed\n        for name, dz in (("high", H_HIGH), ("pre", H_PRE), ("fin", 0.0)):\n            pos = GB + EZ * dz - R @ Eb\n            q, reach = api.ik(pos, mat_to_quat(R), q_init=q_prev)\n            q = np.asarray(q, float)\n            if not reach or np.min(np.minimum(q - lim[:, 0], lim[:, 1] - q)) < 0.05:\n                break\n            poses[name] = (pos, R, q)\n            q_prev = q\n        if len(poses) < 3:\n            continue\n        cost = np.abs(poses["high"][2] - q_seed).sum() + 3 * np.abs(poses["fin"][2] - poses["high"][2]).sum()\n        if verbose:\n            print(f"  psi={np.degrees(psi):6.1f} cost={cost:.2f} tcp_z_dir={np.round(R[:, 2], 2)}")\n        if best is None or cost < best["cost"]:\n            best = dict(psi=psi, cost=cost, poses=poses, Eb=Eb, Ec=Ec)\n    return best\n\n\ndef in_tcp(T, p):\n    return T[:3, :3].T @ (p - T[:3, 3])\n\n\ndef finger_clearance(g, R):\n    """Number of heightmap points (not the rod) inside the two finger footprints, above the board."""\n    y = R[:, 1]; x = R[:, 0]\n    n = 0\n    for sgn in (-1, 1):\n        fc = g + sgn * y * (W_PRE / 2 + 0.010)\n        d = HM - fc\n        inside = (np.abs(d @ x) < 0.014) & (np.abs(d @ y) < 0.012) & (HM[:, 2] > BOARD_Z + 0.003) \\\n            & (HM[:, 2] < g[2] + 0.06)\n        n += int(inside.sum())\n    return n\n\n\na_h = R0E1 - R0E0; a_h[2] = 0; a_h = unit(a_h)\ny_ax = unit(np.cross(EZ, a_h))\nif y_ax @ np.array([0, -1.0, 0]) < 0:\n    y_ax = -y_ax\nz_ax = -EZ\nR_GRASP = np.column_stack([np.cross(y_ax, z_ax), y_ax, z_ax])\nQ_GRASP = mat_to_quat(R_GRASP)\nq_now = np.asarray(api.observe()["joints"], float)\nTCP_Z = BOARD_Z + TCP_ABOVE_BOARD\n\ncands = []\nfor k, (eA, eB) in enumerate(((R0E0, R0E1), (R0E1, R0E0))):    # eA = end to hold (top), eB = bottom\n    for s in (0.011, 0.016, 0.021):\n        g = eA + unit(eB - eA) * s\n        g = np.array([g[0], g[1], TCP_Z])\n        Tg = Tm(g, R_GRASP)\n        ax_pt = (eA + eB) / 2\n        # rod centred between the fingers: project its axis into the TCP y=0 plane\n        Eb_t = in_tcp(Tg, eB); Ec_t = in_tcp(Tg, eA)\n        Eb_t[1] = 0.0; Ec_t[1] = 0.0\n        coll = finger_clearance(g, R_GRASP)\n        plan = plan_insert(Eb_t, Ec_t, q_now) if coll < 15 else None\n        cost = (plan["cost"] if plan else 1e9) + 20 * (s - 0.011) + 0.5 * coll\n        print(f"grasp cand end{k} s={s:.3f}: g={np.round(g, 4).tolist()} finger_pts={coll} "\n              f"plan={\'none\' if plan is None else round(plan[\'cost\'], 2)}")\n        cands.append((cost, k, s, g, Eb_t, Ec_t, plan, coll))\ncands.sort(key=lambda c: c[0])\n_, K_SEL, S_SEL, G_PT, EB_PRED, EC_PRED, PLAN, COLL = cands[0]\nprint("selected end", K_SEL, "s", S_SEL, "finger_pts", COLL, "plan feasible", PLAN is not None)\n\napi.move_to(G_PT + EZ * 0.10, Q_GRASP, timeout_s=3.0)\napi.set_gripper(width=W_PRE, hold_s=0.3)\napi.move_to(G_PT + EZ * 0.02, Q_GRASP, timeout_s=2.0)\napi.move_to(G_PT, Q_GRASP, timeout_s=1.5, tol=0.004, gain=0.6)\no = api.observe()\nprint("at grasp tcp", np.round(o["tcp_pos"], 4), "target", np.round(G_PT, 4), "wrench", np.round(o["tcp_wrench_ext"], 2))\napi.set_gripper(open_=False, hold_s=0.6)\nW_CLOSED = float(api.observe()["gripper_width"])\napi.move_to(G_PT + EZ * 0.07, Q_GRASP, timeout_s=2.0, gain=0.7)\napi.wait(0.12)\n\nT_LIFT = tcp_T()\nFIT1 = fit_rod()\nok = False\nev = "no mask fit after lift"\nEB_MEAS = EC_MEAS = None\nif FIT1 is not None:\n    tcp = T_LIFT[:3, 3]\n    m0, m1 = rod_ends(FIT1, anchor_far_from=tcp)\n    mb, mc = (m0, m1) if np.linalg.norm(m0 - tcp) > np.linalg.norm(m1 - tcp) else (m1, m0)\n    EB_MEAS, EC_MEAS = in_tcp(T_LIFT, mb), in_tcp(T_LIFT, mc)\n    ctr = (m0 + m1) / 2\n    dxy = np.linalg.norm(ctr[:2] - tcp[:2])\n    ok = ctr[2] > ROD_CTR0[2] + 0.04 and dxy < 0.04 and FIT1["n"] > 150\n    ev = (f"mask fit rod ctr z {ROD_CTR0[2]:.3f}->{ctr[2]:.3f}, ctr-tcp xy {dxy*1000:.0f}mm, ext {FIT1[\'ext\']*1000:.0f}mm, "\n          f"rms {FIT1[\'rms\']*1000:.2f}mm, width {W_CLOSED:.4f}")\n    print("rod in tcp: pred bottom", EB_PRED, "top", EC_PRED, "\\n            meas bottom", EB_MEAS, "top", EC_MEAS)\nprint(ev)\nstage_done(ok, ev)\n', True), ('insert', 'stages/03_insert.py', '# insert: turn the rod vertical over the hole, correct xy with the camera fit of the hanging rod,\n# descend, release so it drops to the bottom, back off; verify with the mask fit.\nuse_meas = (EB_MEAS is not None and np.linalg.norm(EB_MEAS - EB_PRED) < 0.008\n            and np.linalg.norm(EC_MEAS - EC_PRED) < 0.012)\nEB_USE, EC_USE = (EB_MEAS, EC_MEAS) if use_meas else (EB_PRED, EC_PRED)\nprint("rod-in-hand model:", "measured" if use_meas else "predicted")\nq_now = np.asarray(api.observe()["joints"], float)\nplan = plan_insert(EB_USE, EC_USE, q_now, verbose=True)\nif plan is None and use_meas:\n    EB_USE, EC_USE = EB_PRED, EC_PRED\n    plan = plan_insert(EB_USE, EC_USE, q_now, verbose=True)\nif plan is None:\n    stage_done(False, "no reachable vertical insertion pose")\n\nR_ins = plan["poses"]["high"][1]\nQ_INS = mat_to_quat(R_ins)\nprint("insert psi", np.degrees(plan["psi"]), "tcp z dir", np.round(R_ins[:, 2], 3))\napi.move_to_joints(plan["poses"]["high"][2], timeout_s=4.0)\npre = plan["poses"]["pre"][0].copy()\napi.move_to(pre, Q_INS, timeout_s=3.0)\n\n# closed-loop xy alignment of the hanging rod\'s axis over the hole axis\ncorr = np.zeros(3)\nfor it in range(3):\n    api.wait(0.1)\n    f = fit_rod()\n    if f is None:\n        print("align: no fit"); break\n    T = tcp_T()\n    m0, m1 = rod_ends(f, anchor_far_from=T[:3, 3])\n    mb = m0 if m0[2] < m1[2] else m1\n    a = unit(m1 - m0)\n    # axis point at the goal-bottom height (extrapolate the line), compare with the goal axis\n    lam = (GB[2] - mb[2]) / a[2] if abs(a[2]) > 0.5 else 0.0\n    at_goal = mb + lam * a\n    err = GB - at_goal\n    err[2] = (GB[2] + H_PRE) - mb[2]\n    print(f"align {it}: rod bottom {np.round(mb, 4)} axis {np.round(a, 3)} ext {f[\'ext\']*1000:.0f}mm "\n          f"rms {f[\'rms\']*1000:.2f} xy err {np.round(err[:2]*1000, 1)}mm z err {err[2]*1000:.1f}mm")\n    if np.linalg.norm(err[:2]) < 0.0005 and abs(err[2]) < 0.002:\n        break\n    if np.linalg.norm(err) > 0.02:\n        print("align: correction too large, ignored"); break\n    corr += err\n    api.move_to(pre + corr, Q_INS, timeout_s=1.5, tol=0.003)\n\nfin = plan["poses"]["fin"][0] + corr\nfor dz in (0.02, 0.01, 0.004):\n    api.move_to(fin + EZ * dz, Q_INS, timeout_s=1.5, tol=0.004, gain=0.5)\n    o = api.observe()\n    F = np.asarray(o["tcp_wrench_ext"], float)\n    print(f"descend dz={dz:.3f} tcp z={o[\'tcp_pos\'][2]:.4f} want {fin[2] + dz:.4f} F={np.round(F[:3], 2)}")\napi.set_gripper(open_=True, hold_s=0.4)\no = api.observe()\napi.move_to(np.asarray(o["tcp_pos"]) - R_ins[:, 2] * 0.06, Q_INS, timeout_s=2.0)\napi.move_to(np.asarray(api.observe()["tcp_pos"]) + EZ * 0.10, Q_INS, timeout_s=2.0)\napi.wait(0.2)\n\nf = fit_rod()\nok = False\nev = "no mask fit"\nif f is not None:\n    top = f["p1"] if f["p1"][2] > f["p0"][2] else f["p0"]\n    a = unit(f["p1"] - f["p0"])\n    lam = (GT[2] - top[2]) / a[2] if abs(a[2]) > 0.5 else 0.0\n    xy = np.linalg.norm((top + lam * a - GT)[:2])\n    dz = top[2] - GT[2]\n    ok = abs(a[2]) > 0.98 and xy < 0.002 and abs(dz) < 0.0025\n    ev = f"mask fit: axis z {abs(a[2]):.3f}, top z {top[2]:.4f} vs goal {GT[2]:.4f} ({dz*1000:+.1f}mm), axis xy off {xy*1000:.1f}mm"\ntr = tracker()\nif tr:\n    print("tracker ends", np.round(tr[0], 4), np.round(tr[1], 4))\nprint(ev)\nstage_done(ok, ev)\n', True)]   # (name, file, source, strict): a strict stage stops the policy on FAIL


class StageFailed(Exception):
    pass


def policy(api):
    ns = dict(api=api, np=np)
    cur = [None, True]

    def stage_done(ok, evidence=""):
        api._rec("stage_done", stage=cur[0], ok=bool(ok), evidence=str(evidence)[:200])
        print(f"[STAGE {cur[0]}] {'PASS' if ok else 'FAIL'} {evidence}", flush=True)
        if not ok and cur[1] and getattr(api, "strict_stages", True):
            raise StageFailed(cur[0])

    ns["stage_done"] = stage_done
    try:
        for name, fname, src, strict in STAGES:
            cur[0], cur[1] = name, strict
            print(f"=== {name} ({fname}) ===", flush=True)
            try:
                exec(compile(src, fname, "exec"), ns)
            except (StageFailed, _api.EpisodeOver, _api.LevelError):
                raise
            except Exception as e:
                traceback.print_exc()
                api._rec("stage_done", stage=name, ok=False, evidence=f"exception {type(e).__name__}: {e}"[:200])
                print(f"[STAGE {name}] FAIL exception {type(e).__name__}: {e}", flush=True)
                raise StageFailed(name)
    except StageFailed:
        return                        # the episode goes on without the policy
